// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "./.open-next/worker.js";

const WWW_HOST = "www.homayar.com";
const CANONICAL_ORIGIN = "https://homayar.com";

const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    // "www.homayar.com." (a trailing dot) is the same DNS name as "www.homayar.com".
    const host = url.hostname.replace(/\.$/, "");
    // Runs before OpenNext, so it covers every path, also /api/* and /_next/* that proxy.ts skips.
    if (host === WWW_HOST) {
      return Response.redirect(`${CANONICAL_ORIGIN}${url.pathname}${url.search}`, 301);
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;
